practice_challenges.starter_code:
def parse_all(values):
    good, errors = [], []
    for v in values:
        try:
            good.append(int(v))
        except ValueError:
            pass  # TODO: remember the problem instead of dropping it
    # TODO: if any errors were collected, raise ONE ExceptionGroup("parse failed", errors)
    return good

# --- demo (do not change) ---
print(parse_all(["1", "2"]))
try:
    parse_all(["4", "x", "7", "y"])
except* ValueError as eg:
    print(len(eg.exceptions), [str(e) for e in eg.exceptions])

practice_challenges.test_code:
assert parse_all([]) == []
assert parse_all(["5", "6"]) == [5, 6]
try:
    parse_all(["1", "oops", "3", "bad", "z"])
except ExceptionGroup as g:
    assert g.message == "parse failed", g.message
    assert len(g.exceptions) == 3, len(g.exceptions)
    assert all(isinstance(e, ValueError) for e in g.exceptions)
    assert [str(e) for e in g.exceptions] == ["bad value: 'oops'", "bad value: 'bad'", "bad value: 'z'"]
else:
    raise AssertionError("expected an ExceptionGroup for bad input")
try:
    parse_all(["x"])
except ExceptionGroup as g:
    assert len(g.exceptions) == 1   # even one problem is wrapped in a group
else:
    raise AssertionError("a single bad value must still raise an ExceptionGroup")

uth_example:
errors = []
for raw in ["12", "x", "7", "y"]:
    try:
        print("ok", int(raw))
    except ValueError as exc:
        errors.append(exc)

print("collected", len(errors))
try:
    if errors:
        raise ExceptionGroup("batch failed", errors)
except* ValueError as group:
    print(type(group).__name__, len(group.exceptions))
    print([type(e).__name__ for e in group.exceptions])

